// AUTO-GENERATED from "Business Registration Customer Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms under which Seventh Sky will coordinate and manage Business Registration Services requested by the Client.</p><p style=\"margin:6px 0;\">Depending on the nature of the project, services may be provided directly by Seventh Sky or by qualified third-party professionals appointed or coordinated by Seventh Sky.</p><p style=\"margin:6px 0;\">The specific services, pricing and project requirements for each engagement will be confirmed in the relevant Quotation and Work Order.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement becomes effective on the date it is signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">all agreed Services have been completed;</li><li style=\"margin:2px 0;\">all outstanding payments have been made; and</li><li style=\"margin:2px 0;\">all agreed deliverables have been provided,</li></ul><p style=\"margin:6px 0;\">unless terminated earlier under this Agreement.</p><p style=\"margin:6px 0;\">Where ongoing corporate compliance or annual filing services are engaged, this Agreement continues for the period specified in the approved Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">The Client may request one or more of the following services.</p><p style=\"margin:6px 0;\">Only the services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Trade Licence Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ New Trade Licence Application</li><li style=\"margin:2px 0;\">☐ Trade Licence Renewal</li><li style=\"margin:2px 0;\">☐ Trade Licence Amendment</li><li style=\"margin:2px 0;\">☐ Municipality Documentation</li><li style=\"margin:2px 0;\">☐ City Corporation Documentation</li><li style=\"margin:2px 0;\">☐ Local Authority Coordination</li><li style=\"margin:2px 0;\">☐ Business Address Documentation</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Business Registration Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Sole Proprietorship Registration</li><li style=\"margin:2px 0;\">☐ Partnership Registration</li><li style=\"margin:2px 0;\">☐ Private Limited Company Registration</li><li style=\"margin:2px 0;\">☐ Public Limited Company Registration</li><li style=\"margin:2px 0;\">☐ Business Name Registration</li><li style=\"margin:2px 0;\">☐ RJSC Registration Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Corporate Documentation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Memorandum of Association Coordination</li><li style=\"margin:2px 0;\">☐ Articles of Association Coordination</li><li style=\"margin:2px 0;\">☐ Shareholder Documentation</li><li style=\"margin:2px 0;\">☐ Director Documentation</li><li style=\"margin:2px 0;\">☐ Company Resolution Preparation</li><li style=\"margin:2px 0;\">☐ Statutory Documentation</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Tax &amp; Regulatory Registration</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ TIN Registration Coordination</li><li style=\"margin:2px 0;\">☐ BIN Registration Coordination</li><li style=\"margin:2px 0;\">☐ VAT Registration Coordination</li><li style=\"margin:2px 0;\">☐ Tax Registration Support</li><li style=\"margin:2px 0;\">☐ Regulatory Compliance Documentation</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Corporate Compliance Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Annual Return Coordination</li><li style=\"margin:2px 0;\">☐ Company Information Update</li><li style=\"margin:2px 0;\">☐ Regulatory Filing Support</li><li style=\"margin:2px 0;\">☐ Corporate Record Maintenance</li><li style=\"margin:2px 0;\">☐ Company Secretarial Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Business Advisory Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Business Structure Consultation</li><li style=\"margin:2px 0;\">☐ Registration Process Guidance</li><li style=\"margin:2px 0;\">☐ Documentation Review</li><li style=\"margin:2px 0;\">☐ Regulatory Compliance Advice</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Certified Document Coordination</li><li style=\"margin:2px 0;\">☐ Government Authority Liaison</li><li style=\"margin:2px 0;\">☐ Translation Coordination</li><li style=\"margin:2px 0;\">☐ Other</li></ul><p style=\"margin:6px 0;\">Additional services may be included by written agreement.</p>"],
  ["PROJECT DETAILS", "<p style=\"margin:6px 0;\">The details of each project shall be recorded in Schedule B or the approved Work Order, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Client Name</li></ul><p style=\"margin:6px 0;\">Business Name</p><p style=\"margin:6px 0;\">Registration Type</p><p style=\"margin:6px 0;\">Selected Services</p><p style=\"margin:6px 0;\">Scope of Work</p><p style=\"margin:6px 0;\">Government Authorities Involved</p><p style=\"margin:6px 0;\">Estimated Timeline</p><p style=\"margin:6px 0;\">Agreed Price</p><p style=\"margin:6px 0;\">Payment Schedule</p><p style=\"margin:6px 0;\">Special Requirements</p><p style=\"margin:6px 0;\">If any inconsistency exists between this Agreement and the Work Order, the Work Order prevails for that project only.</p>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">coordinate the requested services;</li><li style=\"margin:2px 0;\">provide quotations and Work Orders;</li><li style=\"margin:2px 0;\">coordinate qualified third-party professionals where required;</li><li style=\"margin:2px 0;\">monitor project progress;</li><li style=\"margin:2px 0;\">keep the Client reasonably informed;</li><li style=\"margin:2px 0;\">coordinate communication with relevant stakeholders where applicable;</li><li style=\"margin:2px 0;\">manage project administration and documentation; and</li><li style=\"margin:2px 0;\">endeavour to ensure the Services are delivered professionally and within agreed timeframes.</li></ul><p style=\"margin:6px 0;\">Unless expressly stated otherwise, Seventh Sky acts as the project coordinator and contract administrator and does not act as a government authority or guarantee approvals issued by any government department or regulatory body.</p>"],
  ["CLIENT RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Client agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide complete and accurate information;</li><li style=\"margin:2px 0;\">provide genuine supporting documents;</li><li style=\"margin:2px 0;\">promptly provide additional information when requested;</li><li style=\"margin:2px 0;\">review and approve quotations before work commences;</li><li style=\"margin:2px 0;\">promptly advise Seventh Sky of any changes affecting the project;</li><li style=\"margin:2px 0;\">pay all agreed fees in accordance with this Agreement;</li><li style=\"margin:2px 0;\">pay applicable government fees and statutory charges; and</li><li style=\"margin:2px 0;\">cooperate throughout the registration process.</li></ul><p style=\"margin:6px 0;\">Delays caused by the Client may result in revised project timelines or additional costs.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before any work begins, Seventh Sky will provide the Client with a Quotation and, where applicable, a Work Order outlining:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">selected services;</li><li style=\"margin:2px 0;\">scope of work;</li><li style=\"margin:2px 0;\">estimated project timeline;</li><li style=\"margin:2px 0;\">agreed pricing;</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected deliverables; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Work will commence only after the Client accepts the Quotation or Work Order.</p><p style=\"margin:6px 0;\">If the Client requests additional services after approval, a revised quotation or variation may be required.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The total project cost will be specified in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">consultation fees;</li><li style=\"margin:2px 0;\">professional service fees;</li><li style=\"margin:2px 0;\">documentation preparation;</li><li style=\"margin:2px 0;\">registration coordination;</li><li style=\"margin:2px 0;\">government liaison;</li><li style=\"margin:2px 0;\">regulatory filing support;</li><li style=\"margin:2px 0;\">administrative charges;</li><li style=\"margin:2px 0;\">approved third-party professional fees (where applicable);</li><li style=\"margin:2px 0;\">government fees and statutory charges (where applicable); and</li><li style=\"margin:2px 0;\">any approved additional services.</li></ul><p style=\"margin:6px 0;\">The Client agrees to pay the agreed amount in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Government fees, stamp duties, taxes and statutory charges are payable by the Client unless otherwise stated in the approved Quotation or Work Order.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Registration &amp; Documentation Services</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Deposit upon acceptance of the Quotation or Work Order.</li></ul><p style=\"margin:6px 0;\">Progress payment (where applicable).</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Final payment upon completion of the agreed Services or submission of the relevant application.</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Ongoing Compliance Services</p><p style=\"margin:6px 0;\">Where the Client engages Seventh Sky for ongoing compliance services (such as annual returns or regulatory filing support), payment may be made:</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Monthly</li><li style=\"margin:2px 0;\">☐ Quarterly</li><li style=\"margin:2px 0;\">☐ Half-Yearly</li><li style=\"margin:2px 0;\">☐ Annually</li></ul><p style=\"margin:6px 0;\">as specified in the approved Work Order.</p><p style=\"margin:6px 0;\">Invoices are payable within the agreed payment period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payments may result in suspension or delay of the Services.</p>"],
  ["GOVERNMENT AUTHORITIES & REGULATORY APPROVALS", "<p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">registration approvals are issued solely by the relevant government authority;</li><li style=\"margin:2px 0;\">Seventh Sky cannot guarantee approval of any application;</li><li style=\"margin:2px 0;\">government processing times may vary;</li><li style=\"margin:2px 0;\">government authorities may request additional information or supporting documents;</li><li style=\"margin:2px 0;\">approval, rejection or delay remains at the discretion of the relevant authority.</li></ul><p style=\"margin:6px 0;\">Where additional information is requested, Seventh Sky will use reasonable efforts to coordinate the response with the Client.</p>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project timeframes may be affected by:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">government processing times;</li><li style=\"margin:2px 0;\">availability of required documents;</li><li style=\"margin:2px 0;\">delays by the Client;</li><li style=\"margin:2px 0;\">regulatory reviews;</li><li style=\"margin:2px 0;\">public holidays;</li><li style=\"margin:2px 0;\">system outages affecting government agencies;</li><li style=\"margin:2px 0;\">legislative changes; or</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Client reasonably informed and provide an updated estimated completion timeframe where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">A variation occurs where the Client requests work outside the approved scope of Services or where additional work becomes necessary.</p><p style=\"margin:6px 0;\">Examples include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional registrations;</li><li style=\"margin:2px 0;\">amendments to submitted applications;</li><li style=\"margin:2px 0;\">additional company documentation;</li><li style=\"margin:2px 0;\">shareholder or director changes;</li><li style=\"margin:2px 0;\">regulatory responses;</li><li style=\"margin:2px 0;\">additional government submissions;</li><li style=\"margin:2px 0;\">certified document preparation;</li><li style=\"margin:2px 0;\">translation services; or</li><li style=\"margin:2px 0;\">additional Client requests.</li></ul><p style=\"margin:6px 0;\">Where practical, Seventh Sky will advise the Client of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the additional work;</li><li style=\"margin:2px 0;\">any additional charges; and</li><li style=\"margin:2px 0;\">any impact on the project timeline.</li></ul><p style=\"margin:6px 0;\">No variation will proceed without the Client's approval unless immediate action is reasonably necessary to protect the Client's interests or comply with legal requirements.</p>"],
  ["PROFESSIONAL SERVICES & THIRD-PARTY PROVIDERS", "<p style=\"margin:6px 0;\">The Client acknowledges that certain Services may be performed or supported by qualified professionals, consultants or specialist service providers appointed or coordinated by Seventh Sky.</p><p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">professional advisers remain responsible for the advice they provide;</li><li style=\"margin:2px 0;\">government authorities remain responsible for registration decisions;</li><li style=\"margin:2px 0;\">third-party professionals remain responsible for their own professional services; and</li><li style=\"margin:2px 0;\">Seventh Sky remains responsible for coordinating the project and assisting the Client throughout the engagement.</li></ul>"],
  ["DOCUMENTATION, WARRANTIES & COMPLETION", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable care and skill in coordinating the Services under this Agreement.</p><p style=\"margin:6px 0;\">Upon completion of the agreed Services, Seventh Sky will provide the Client with the relevant documents or confirmation of submission, as applicable.</p><p style=\"margin:6px 0;\">Where Services involve third-party professionals or government authorities:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">professional advice remains the responsibility of the relevant professional;</li><li style=\"margin:2px 0;\">government approvals remain the responsibility of the relevant authority;</li><li style=\"margin:2px 0;\">official registration certificates and licences are issued by the relevant authority; and</li><li style=\"margin:2px 0;\">statutory processing remains subject to applicable laws and government procedures.</li></ul><p style=\"margin:6px 0;\">Any warranty relating to third-party professional services shall remain subject to that provider's terms and conditions.</p>"],
  ["CLIENT COMPLAINTS & SERVICE ISSUES", "<p style=\"margin:6px 0;\">If the Client believes that the Services have not been completed in accordance with the approved scope, the Client should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">liaise with the relevant service provider or authority where required;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue; and</li><li style=\"margin:2px 0;\">keep the Client informed of the outcome.</li></ul><p style=\"margin:6px 0;\">Where errors arise due to Seventh Sky's administrative oversight, reasonable efforts will be made to rectify the matter promptly.</p><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available to the Client under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">To the extent permitted by the laws of Bangladesh:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Seventh Sky is responsible for coordinating and administering the Services with reasonable care and skill.</li><li style=\"margin:2px 0;\">Professional advice remains the responsibility of the qualified consultant or professional providing that advice.</li></ul><p style=\"margin:6px 0;\">Government authorities remain responsible for approvals, registrations, licences and statutory decisions.</p><p style=\"margin:6px 0;\">Neither Party shall be liable for delays or failures resulting from circumstances beyond their reasonable control.</p>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">Except where liability cannot legally be excluded or limited, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">delays caused by government authorities;</li><li style=\"margin:2px 0;\">rejection of applications by government authorities;</li><li style=\"margin:2px 0;\">inaccurate or incomplete information supplied by the Client;</li><li style=\"margin:2px 0;\">actions or decisions of third-party professionals;</li><li style=\"margin:2px 0;\">legislative or regulatory changes;</li><li style=\"margin:2px 0;\">indirect or consequential losses;</li><li style=\"margin:2px 0;\">loss of business opportunity, profit or goodwill; or</li><li style=\"margin:2px 0;\">events beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where permitted by law, Seventh Sky's total liability arising from a project shall not exceed the amount paid by the Client for the affected Services.</p><p style=\"margin:6px 0;\">This clause does not exclude liability arising from fraud, wilful misconduct or any liability that cannot legally be excluded.</p>"],
  ["INSURANCE", "<p style=\"margin:6px 0;\">Where appropriate, Seventh Sky may assist the Client in coordinating optional insurance or professional indemnity arrangements through third-party providers.</p><p style=\"margin:6px 0;\">Any insurance:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">is subject to the insurer's acceptance;</li><li style=\"margin:2px 0;\">is governed by the insurer's policy terms;</li><li style=\"margin:2px 0;\">does not guarantee approval of a claim; and</li><li style=\"margin:2px 0;\">is separate from this Agreement.</li></ul><p style=\"margin:6px 0;\">The Client remains responsible for obtaining any insurance they consider necessary unless otherwise agreed in writing.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Each Party agrees to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Personal information will only be collected, used and disclosed for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the requested Services;</li><li style=\"margin:2px 0;\">communicating with the Client;</li><li style=\"margin:2px 0;\">preparing quotations, applications, invoices and Work Orders;</li><li style=\"margin:2px 0;\">complying with legal and regulatory obligations; or</li><li style=\"margin:2px 0;\">other purposes authorised by the Client.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be responsible for delays or failure to perform caused by events beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">civil unrest;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">cyber incidents affecting government systems;</li><li style=\"margin:2px 0;\">major technology failures; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance when reasonably possible.</p>"],
  ["CLIENT ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have reviewed and accepted the Quotation or Work Order before the Services commence;</li><li style=\"margin:2px 0;\">government approvals, registrations and licences remain at the discretion of the relevant authority;</li><li style=\"margin:2px 0;\">project timelines are estimates only and may vary depending on government processing;</li><li style=\"margin:2px 0;\">additional information or documentation may be requested by government authorities;</li><li style=\"margin:2px 0;\">some Services may be delivered by qualified independent professionals coordinated by Seventh Sky; and</li><li style=\"margin:2px 0;\">they have had the opportunity to ask questions and obtain independent legal or professional advice before signing this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">22.1 Suspension</p><p style=\"margin:6px 0;\">Seventh Sky may suspend the Services where:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the Client fails to make payments in accordance with this Agreement;</li><li style=\"margin:2px 0;\">the Client fails to provide required information or supporting documents;</li><li style=\"margin:2px 0;\">the Client provides false, misleading or incomplete information;</li><li style=\"margin:2px 0;\">continuation of the Services would breach applicable laws or regulatory requirements;</li><li style=\"margin:2px 0;\">the Client requests suspension; or</li><li style=\"margin:2px 0;\">continuation of the Services would be unlawful or impracticable.</li></ul><p style=\"margin:6px 0;\">Where practicable, Seventh Sky will notify the Client before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">22.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by giving thirty (30) days' written notice, provided all completed work and outstanding payments are settled.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately if the Client:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">provides false or fraudulent information;</li><li style=\"margin:2px 0;\">refuses to cooperate with reasonable information requests;</li><li style=\"margin:2px 0;\">fails to make payment after receiving written notice; or</li><li style=\"margin:2px 0;\">requests Services that would breach applicable laws or regulatory requirements.</li></ul><p style=\"margin:6px 0;\">The Client may terminate this Agreement before work commences by providing written notice.</p><p style=\"margin:6px 0;\">Where work has already commenced, the Client remains responsible for payment for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Services already performed;</li><li style=\"margin:2px 0;\">professional time incurred;</li><li style=\"margin:2px 0;\">documentation prepared;</li><li style=\"margin:2px 0;\">government applications already lodged;</li><li style=\"margin:2px 0;\">approved third-party costs incurred; and</li><li style=\"margin:2px 0;\">any reasonable expenses incurred before termination.</li></ul><p style=\"margin:6px 0;\">Termination does not affect any rights or obligations that arose before the termination date.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment must be made in writing and signed or electronically accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce a provision does not waive its rights;</li><li style=\"margin:2px 0;\">if any provision is held to be invalid or unenforceable, the remaining provisions remain in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, courier, registered post or email.</li></ul>"],
  ["GOVERNING LAW & DISPUTE RESOLUTION", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to make reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">If the dispute cannot be resolved through negotiation, the Parties may agree to mediation or another recognised alternative dispute resolution process before referring the matter to the competent courts of Bangladesh.</p><p style=\"margin:6px 0;\">Nothing in this clause prevents either Party from seeking urgent legal or equitable relief where necessary.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal or professional advice;</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily; and</li><li style=\"margin:2px 0;\">agree to be legally bound by its terms.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, including through approved digital signature platforms such as DocuSign. Each signed copy will be deemed an original and together will constitute one Agreement.</p>"],
];
